import{H as e,M as t,U as n,nt as r}from"./chunks/framework.Bdj8QXxy.js";var i=JSON.parse(`{"title":"什么是 Vue DevTools Unlocker？","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"zh/guide/what-is-it.md","filePath":"zh/guide/what-is-it.md"}`),a={name:`zh/guide/what-is-it.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /vue-devtools-unlocker/zh/guide/what-is-it.md for this page in Markdown format</div><h1 id="什么是-vue-devtools-unlocker" tabindex="-1">什么是 Vue DevTools Unlocker？ <a class="header-anchor" href="#什么是-vue-devtools-unlocker" aria-label="Permalink to “什么是 Vue DevTools Unlocker？”">​</a></h1><p>Vue DevTools Unlocker 是一个浏览器扩展，用于在生产环境页面中启用 Vue DevTools 面板。</p><p>在生产构建中，Vue 默认会关闭 DevTools。这个扩展会向页面注入一小段脚本，重新启用 Vue 的 devtools hook，让你的 Vue 应用在生产环境也能像开发环境一样被检查和调试。</p><h2 id="主要特性" tabindex="-1">主要特性 <a class="header-anchor" href="#主要特性" aria-label="Permalink to “主要特性”">​</a></h2><ul><li>在生产环境页面解锁 Vue DevTools 面板。</li><li>同时支持 Vue 2 和 Vue 3。</li><li>当页面存在运行时 Pinia 实例时，可查看 Vue 3 Pinia stores 与 state。</li><li>在扩展弹窗中显示检测到的 Vue 版本。</li><li>无需修改应用源码或构建配置。</li><li>基于浏览器扩展的调试流程，贴合现有开发习惯。</li></ul><h2 id="支持的浏览器" tabindex="-1">支持的浏览器 <a class="header-anchor" href="#支持的浏览器" aria-label="Permalink to “支持的浏览器”">​</a></h2><p>Vue DevTools Unlocker 在以下浏览器扩展商店中提供：</p><ul><li><a href="https://chromewebstore.google.com/detail/vue-devtools-unlocker/fbihgkimpchlnlcnbffhbpcghafemopa" target="_blank" rel="noreferrer">Chrome 扩展商店</a></li><li><a href="https://microsoftedge.microsoft.com/addons/detail/vue-devtools-unlocker/lehadmjlbmlapdkapjoapbhhbcpcoepd" target="_blank" rel="noreferrer">Microsoft Edge 扩展</a></li><li><a href="https://addons.mozilla.org/zh-CN/firefox/addon/vue-devtools-unlocker/" target="_blank" rel="noreferrer">Firefox 扩展</a></li></ul>`,9)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};